  if (!report.initialTemplateCount) {
    report.preparedBaseline = true;
    for (const [suffix, type, content] of [['plain', 2, '  原有中文 @(name)\r\n尾部  '], ['html', 3, '<h2 data-note="原文">@(name)</h2>\r\n<p>中文 &amp; 保留</p>'], ['wechat', 7, '企业微信 @(name)']]) await add(draft(baselinePrefix + '_' + suffix, { type, content, groupName: baselinePrefix, remark: '受保护的既有模板', orderNo: type }));
  }
